/* R2 incremental UI reference; all records fictional, no service/host calls. */
const DOMAIN_REGISTRY=[['graphic','平面设计'],['brand','品牌与 VI'],['type','字体与出版'],['pack','包装设计'],['three','3D 建模与渲染'],['space','空间与展示'],['motion','动效设计'],['video','视频制作'],['audio','音频与声音'],['ui','UI 与交互'],['game','游戏视觉']];
const DOMAIN_NAMES=Object.fromEntries(DOMAIN_REGISTRY);
const ITEMS=[
{id:'poster',name:'海报构图与信息层级',domains:['graphic','brand'],kind:'可调用能力',art:'brand-poster',desc:'根据文案与目标画幅建立清晰层级，保留准确文字。',outputs:['生成包','图片'],software:'Illustrator / Photoshop',scope:'分析 · 目标生成包'},
{id:'vi',name:'品牌识别与视觉延展',domains:['brand','graphic','pack'],kind:'模板与配方',art:'design-orbit',desc:'组织标识、字体、色彩与应用关系，保持品牌一致。',outputs:['生成包','原生工程'],software:'Illustrator / Photoshop',scope:'方案 · 配方'},
{id:'editor',name:'字体层级与出版网格',domains:['type','graphic'],kind:'规范与方法',art:'editorial',desc:'把长文、标题与图像放入可读的网格和阅读节奏。',outputs:['生成包','文档'],software:'InDesign / Illustrator',scope:'方法 · 分析'},
{id:'pack',name:'包装结构与品牌图形',domains:['pack','brand','three'],kind:'可调用能力',art:'packaging',desc:'分开结构尺寸、刀模与视觉图形，说明必须保持的区域。',outputs:['生成包','原生工程'],software:'Illustrator / Blender',scope:'分析 · 目标生成包'},
{id:'3d',name:'产品三维与材质表达',domains:['three','brand'],kind:'可调用能力',art:'three-study',desc:'从相机、比例、结构与材质条件形成制作及核验要求。',outputs:['生成包','图片','原生工程'],software:'Blender',scope:'分析 · 目标生成包'},
{id:'space',name:'空间视觉与透视约束',domains:['space','three','graphic'],kind:'案例与参考',art:'spatial',desc:'保持墙体、视角和比例关系，拆分材质、字面与安装要求。',outputs:['生成包','图片'],software:'Blender / Photoshop',scope:'参考 · 分析'},
{id:'motion',name:'动效节奏与转场设计',domains:['motion','video','three'],kind:'模板与配方',art:'motion',desc:'明确动作、时序与节奏，交付可继续制作的分镜与计划。',outputs:['生成包','视频','原生工程'],software:'After Effects / Blender',scope:'方案 · 配方'},
{id:'video',name:'品牌广告片与剪辑结构',domains:['video','brand','motion','audio'],kind:'可调用能力',art:'video-study',desc:'把镜头、文案、声画关系与输出规格组织成制作目标。',outputs:['生成包','视频','原生工程'],software:'DaVinci Resolve / Premiere Pro',scope:'分析 · 目标生成包'},
{id:'audio',name:'声音层次与配音制作',domains:['audio','video','game'],kind:'可调用能力',art:'audio-study',desc:'整理旁白、音乐、音效的职责、节奏、授权与交付要求。',outputs:['生成包','音频','原生工程'],software:'REAPER / Audition',scope:'分析 · 目标生成包'},
{id:'ui',name:'界面系统与组件状态',domains:['ui','graphic'],kind:'规范与方法',art:'interface',desc:'建立信息架构、视觉变量、组件状态与响应式规范。',outputs:['生成包','代码','原生工程'],software:'Figma / 前端代码',scope:'方法 · 分析'},
{id:'game',name:'游戏视觉与场景气氛',domains:['game','three','ui','audio'],kind:'案例与参考',art:'game-study',desc:'明确场景层次、角色/界面职责与可复用视觉方向。',outputs:['生成包','图片','原生工程'],software:'Blender / Photoshop',scope:'参考 · 分析'},
{id:'teaching',name:'知识图解与教学表达',domains:['graphic','motion','video','ui'],scene:'教学表达',kind:'可调用能力',art:'teaching',desc:'围绕学习目标选择图解、演示与练习，保留来源和内容版本。',outputs:['生成包','图片','视频','代码'],software:'按内容选择实际工具',scope:'表达方案'}];
const EXTRA={poster:['几何构成','信息层级'],vi:['几何构成','视觉系统'],editor:['编辑排版','阅读网格'],pack:['几何构成','结构约束'],'3d':['几何构成','材质表达'],space:['几何构成','透视约束'],motion:['电影感','时序设计'],video:['电影感','声画叙事'],audio:['电影感','声画叙事'],ui:['简洁界面','视觉系统'],game:['电影感','材质表达'],teaching:['信息图解','知识表达']};
ITEMS.forEach(x=>{[x.style,x.method]=EXTRA[x.id];});
const FACETS={style:[...new Set(ITEMS.map(x=>x.style))],method:[...new Set(ITEMS.map(x=>x.method))],software:[...new Set(ITEMS.flatMap(x=>x.software.split(' / ')))]};
let VIEW={query:'',domain:'all',kind:'全部资产',output:'all',scene:'all',range:'all',style:'all',method:'all',software:'all',layout:'grid'};
let picked=ITEMS.find(x=>x.id==='video'),taskDomains=['brand','three','video'];
let formDraft={};try{const saved=JSON.parse(localStorage.getItem('dl-r2-local-draft')||'null');if(saved){formDraft=saved.fields||{};picked=ITEMS.find(x=>x.id===saved.asset)||picked;taskDomains=saved.domains||taskDomains;}}catch(e){}
function persistDraft(){try{localStorage.setItem('dl-r2-local-draft',JSON.stringify({fields:formDraft,asset:(typeof taskAsset==='undefined'?picked:taskAsset).id,domains:taskDomains}));}catch(e){toast('浏览器无法保存草稿，请保留当前页面。');}}
let taskAsset=picked;
const OLD_INPUT=input,OLD_RESULT=result,OLD_ATTACH=attach;
function readHash(){const raw=location.hash.slice(1)||'catalog';const [route,q='']=raw.split('?');const params=new URLSearchParams(q);if(route==='catalog'){VIEW.domain=params.get('domain')||VIEW.domain;if(params.has('q'))VIEW.query=params.get('q');}if(route==='capability'&&params.has('id'))picked=ITEMS.find(x=>x.id===params.get('id'))||ITEMS[0];return route;}
const mediaRows=()=>ITEMS.filter(c=>(VIEW.domain==='all'||c.domains.includes(VIEW.domain))&&(VIEW.kind==='全部资产'||c.kind===VIEW.kind)&&(VIEW.output==='all'||c.outputs.includes(VIEW.output))&&(VIEW.scene==='all'||c.scene===VIEW.scene)&&(VIEW.style==='all'||c.style===VIEW.style)&&(VIEW.method==='all'||c.method===VIEW.method)&&(VIEW.software==='all'||c.software.split(' / ').includes(VIEW.software))&&(VIEW.range==='all'||(VIEW.range==='analysis'&&c.scope.includes('分析')))&&(c.name+c.desc+c.software+c.style+c.method+c.domains.map(d=>DOMAIN_NAMES[d]).join('')).toLowerCase().includes(VIEW.query.toLowerCase())).sort((a,b)=>Number(b.domains[0]===VIEW.domain)-Number(a.domains[0]===VIEW.domain));
function card(c){return `<article class="cap-card r2-card" data-component="能力-${c.id}">${art(c.art,'')}<div class="card-body"><div class="row spread"><small>${c.kind}</small>${badge('示例')}</div><h3>${c.name}</h3><p>${c.desc}</p><div class="domain-tags">${c.domains.slice(0,3).map(d=>`<span>${DOMAIN_NAMES[d]}</span>`).join('')}</div><div class="card-bottom"><span>${c.scope}<br><small>执行 / 原生交付待核验</small></span><button data-open="${c.id}">查看详情</button></div></div></article>`;}
function catalogR2(){const name=VIEW.domain==='all'?'全部能力资产':DOMAIN_NAMES[VIEW.domain]||'全部能力资产';const rows=mediaRows();return head('CAPABILITY ASSETS / R2',name,'按领域找入口，按类型、风格、软件与交付条件筛选；跨领域能力复用同一记录。',btn('开始新制作','input','primary'))+`<label class="mobile-domain">设计领域<select id="mobile-domain">${[['all','全部领域'],...DOMAIN_REGISTRY].map(([id,n])=>`<option value="${id}" ${VIEW.domain===id?'selected':''}>${n}</option>`).join('')}</select></label><div class="catalog-intro" data-component="目录引导"><div><strong>从你要完成的设计目标出发。</strong><span>每项能力都说明用途、条件和实际范围；示例不代表软件已经接通。</span></div>${badge(DOMAIN_REGISTRY.length+' 个设计领域','blue')}</div><div class="tabs asset-tabs" aria-label="资产类型">${['全部资产','可调用能力','规范与方法','案例与参考','模板与配方'].map(k=>`<button class="${VIEW.kind===k?'selected':''}" data-kind="${k}">${k}</button>`).join('')}</div><div class="r2-filters" data-component="组合筛选"><label class="r2-query"><span class="sr-only">搜索当前资产</span><input id="r2-query" type="search" placeholder="搜索能力、目标、方法或软件" value="${escapeText(VIEW.query)}"></label><select id="r2-output" aria-label="交付类型">${['all','生成包','图片','视频','音频','原生工程','代码'].map(v=>`<option value="${v}" ${VIEW.output===v?'selected':''}>${v==='all'?'全部交付类型':v}</option>`).join('')}</select><select id="r2-range" aria-label="实际能力范围"><option value="all">全部能力范围</option><option value="analysis" ${VIEW.range==='analysis'?'selected':''}>可分析</option><option value="execution" ${VIEW.range==='execution'?'selected':''}>执行已核验</option></select><button data-r2="more" aria-expanded="false">更多筛选</button></div><div class="r2-more hidden" id="r2-more"><label>使用场景<select id="r2-scene"><option value="all">全部场景</option><option value="教学表达" ${VIEW.scene==='教学表达'?'selected':''}>教学表达</option></select></label>${[['style','视觉风格'],['method','设计方法'],['software','软件候选']].map(([key,label])=>`<label>${label}<select id="r2-${key}"><option value="all">全部${label}</option>${FACETS[key].map(x=>`<option ${VIEW[key]===x?'selected':''}>${x}</option>`).join('')}</select></label>`).join('')}</div><div class="r2-active row spread"><div class="row">${badge(VIEW.domain==='all'?'全部领域':name,'blue')}<small id="r2-count">${rows.length} 条演示记录</small><button class="ghost" data-r2="clear">清除筛选</button></div><div class="row"><button data-r2="grid" aria-pressed="${VIEW.layout==='grid'}">卡片</button><button data-r2="list" aria-pressed="${VIEW.layout==='list'}">列表</button></div></div><div class="cards r2-cards ${VIEW.layout==='list'?'as-list':''}" id="r2-items">${rows.map(card).join('')}</div><div id="r2-empty" class="empty-state ${rows.length?'hidden':''}" data-component="无匹配状态"><h2>没有符合当前条件的记录</h2><p>领域入口仍保留。调整筛选，或直接描述需求；执行资格未知不会显示成已支持。</p><div class="row"><button data-r2="clear">清除筛选</button>${btn('描述新需求','input','primary')}</div></div>`;}
function capabilityR2(){return head('CAPABILITY DETAIL',picked.name,'能力、方法、参考与配方采用对应详情；执行资格按实际证据单独声明。',`<button data-use="${picked.id}" class="primary">用于本次制作</button>`)+`<div class="grid2"><div class="stack">${panel('示例与用途',art(picked.art,'media large')+`<p>${picked.desc}</p><div class="domain-tags">${picked.domains.map(d=>`<span>${DOMAIN_NAMES[d]}</span>`).join('')}</div>`)}${panel('输入、目标与检查',numbered([['确认内容与约束','文本、图像、声音或工程引用分别声明；强约束与偏好分开。'],['选用实际可用路线','读取工具版本、能力资格和权限；不能满足时提供目标生成包。'],['验证实际产物','视觉/听觉核对、原生结构读回与真人结论分别保存。']]))}</div><div class="stack">${panel('能力范围',facts([['资产类型',picked.kind],['领域',picked.domains.map(d=>DOMAIN_NAMES[d]).join(' / ')],['交付目标',picked.outputs.join(' / ')],['示例范围',picked.scope],['软件候选',picked.software],['真实执行','未验证，不能声称已接通'],['知识引用','生产读取获准的 AAOS revision'],['来源 / 限制','当前插图为样例，未证明用户宿主能力']]))}${notice('查看详情不改变目录筛选。进入制作后携带能力引用、领域与交付目标。')}${btn('返回目录','catalog')}</div></div>`;}
function inputR2(){return head('ANALYZE & MAKE / R2','先明确目标，再选择制作路线。','领域和能力是本次任务的上下文；约束、素材职责与交付目标分别填写。',btn('查看品牌演示流程','analysis','primary'))+`<section class="task-context" data-component="任务领域与能力"><div><small>本次制作 · 可关联多个领域</small><div class="domain-tags">${taskDomains.map(d=>`<span>${DOMAIN_NAMES[d]}</span>`).join('')}</div></div><div><small>选用的资产</small><strong>${taskAsset.name}</strong></div><button data-r2="edit-domains">调整领域</button></section>`+steps(0)+`<div class="grid2"><div class="stack">${panel('目标与输入',`<label><span class="field-label">要完成什么？</span><textarea id="brief" data-draft="brief">为品牌制作一支 15 秒产品广告片。结合三维产品镜头、准确文案与简洁声音层次。保持品牌冷蓝与银白方向；优先给出可继续制作的分镜与目标包。</textarea></label><div class="upload" style="margin-top:18px">${icon('upload')}<h3>添加素材或参考</h3><small>图片、音视频、文档或工程文件；以环境实际返回的支持类型为准。</small><label class="file-label">选择文件<input id="files" class="sr-only" type="file" multiple aria-label="选择输入素材"></label></div><div id="filelist" class="micro">选择文件仅显示本地名称，原型不上传；重新打开须重新选择文件。</div>`)}${panel('参考职责与约束',`<div class="fields"><label><span>参考的主要用途</span><select data-draft="reference"><option>结构与内容</option><option>视觉风格</option><option>声画节奏</option><option>技术规格</option></select></label><label><span>允许修改范围</span><select data-draft="editrange"><option>允许整体调整</option><option>只调整局部</option><option>结构严格锁定</option></select></label><label class="full"><span>必须保持</span><input data-draft="locks" value="品牌标识 / 文案准确 / 产品比例"></label><label class="full"><span>偏好与可调整部分</span><input data-draft="preferences" value="冷蓝银白 / 留白 / 镜头节奏可调整"></label></div>`)}${notice('草稿仅保存在当前浏览器；当前素材没有上传，真实服务没有接通。')}</div><div class="stack">${panel('交付目标',`<div class="fields"><label class="full"><span>本次交付</span><select id="deliverable" data-draft="deliverable"><option>目标生成包</option><option>分析与建议</option><option>原生可编辑工程（需验证）</option><option>最终媒体文件（需验证）</option></select></label><label class="full"><span>目标软件或工具</span><input data-draft="software" value="${escapeText(taskAsset.software)}"></label><label class="full"><span>尺寸、时长、格式等规格</span><input data-draft="spec" value="1920 × 1080 / 15 秒 / 分镜与生成包"></label><label class="full"><span>准确文案与声音要求</span><textarea data-draft="copy" style="min-height:92px">FORM STUDIES · 产品名称必须准确。旁白、音乐和音效分别说明来源与授权要求。</textarea></label></div>`)}${panel('能力与知识引用',`<div class="sample-chip">${icon('asset')}${taskAsset.name}</div><p class="muted">${taskAsset.scope}。执行与原生交付未验证。</p><div class="line"></div><label class="checkrow"><input type="checkbox" data-draft="teaching"><span>需要知识讲解或教学表达<br><small>学习目标与获准知识版本由 AAOS 提供。</small></span></label>`)}${panel('接下来会发生什么',numbered([['整理目标与条件','确认输入缺口、参考职责和交付规格。'],['给出可用制作路线','计划可预览、修改；实际执行按环境资格判断。'],['保留独立检查结果','产物文件、原生结构和真人意见分别记录。']]))}${btn('导入教学需求','teaching')}</div></div>`;}
function recordsR2(){return head('MAKING RECORDS','继续制作，从最近一次状态开始。','保留输入、知识版本、计划和已确认结果；制作记录按状态组织，领域作为标签。',btn('新建需求','input','primary'))+`<div class="tabs"><span class="selected">全部记录</span><span>进行中</span><span>待继续</span></div>${panel('制作记录',table(['任务','领域','状态','最近确认点','继续'],[['品牌三维广告片','品牌 / 3D / 视频',badge('待继续','amber'),'示例分镜与目标包',btn('继续制作','input')],['FORM STUDIES 海报','平面 / 品牌',badge('待核验','amber'),'草稿 v2',btn('查看结果','result')],['成功信号教学图解','平面 / 动效',badge('方案草稿','blue'),'学习目标与知识引用',btn('查看需求','teaching')]]))}${notice('这些是演示记录，不是实际正在运行的任务。生产恢复须先检查文档与动作回执。')}`;}
const OUTPUT_ROWS=[{art:'video-study',name:'品牌三维广告片',sub:'视频 / 分镜样例',domains:['brand','three','video'],type:'视频',route:'plan'},{art:'version-after',name:'FORM STUDIES 海报',sub:'SVG 草稿 v2',domains:['graphic','brand'],type:'图片',route:'result'},{art:'teaching',name:'成功信号教学图解',sub:'教学表达样例',domains:['graphic','motion'],type:'图片',route:'teaching'}];
function outputCard(x){return `<article class="cap-card">${art(x.art,'')}<div class="card-body"><small>${x.sub}</small><h3>${x.name}</h3><p>示例资产；原生工程、审美确认和正式交付按实际证据核验。</p><div class="domain-tags">${x.domains.map(d=>`<span>${DOMAIN_NAMES[d]}</span>`).join('')}</div><div class="card-bottom">${badge('草稿 / 示例','amber')}${btn('查看与继续',x.route)}</div></div></article>`;}
function resultsR2(){return head('RESULTS & FEEDBACK','成果按交付组织，领域帮助找回。','同一广告片可以归入多个领域，但只维护一个产物版本与交付身份。',btn('新建需求','input','primary'))+`<div class="tabs"><span class="selected">全部成果</span><button data-route="jury">待审阅</button><button data-route="delivery">交付预检</button><button data-route="feedback">反馈与候选</button></div><div class="r2-filters"><input id="output-query" aria-label="检索成果" placeholder="搜索名称、格式或版本"><select id="output-domain" aria-label="成果领域">${[['all','全部领域'],...DOMAIN_REGISTRY].map(([v,t])=>`<option value="${v}">${t}</option>`).join('')}</select><select id="output-type" aria-label="成果交付类型"><option value="all">全部交付类型</option><option>图片</option><option>视频</option><option>音频</option><option>原生工程</option></select></div><div class="outputcards" id="output-items">${OUTPUT_ROWS.map(outputCard).join('')}</div><div class="empty-state hidden" id="output-empty"><h2>没有符合条件的示例成果</h2><p>调整领域、格式或关键词继续查找。</p></div>`;}
function bindOutputFilters(){if(!document.querySelector('#output-query'))return;const refresh=()=>{const q=document.querySelector('#output-query').value.toLowerCase(),d=document.querySelector('#output-domain').value,t=document.querySelector('#output-type').value;const rows=OUTPUT_ROWS.filter(x=>(x.name+x.sub).toLowerCase().includes(q)&&(d==='all'||x.domains.includes(d))&&(t==='all'||x.type===t));document.querySelector('#output-items').innerHTML=rows.map(outputCard).join('');document.querySelector('#output-empty').classList.toggle('hidden',rows.length>0);document.querySelectorAll('#output-items [data-route]').forEach(b=>b.onclick=()=>location.hash=b.dataset.route);};document.querySelector('#output-query').addEventListener('input',refresh);document.querySelector('#output-domain').addEventListener('change',refresh);document.querySelector('#output-type').addEventListener('change',refresh);}
function escapeText(t){return String(t).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
function sidebarR2(group){const nav=[['catalog','asset','能力资产'],['input','make','分析与制作'],['results','result','成果与反馈']];let sub=group==='catalog'?`<div class="navcaption">设计领域</div><nav class="domain-nav" aria-label="设计领域">${[['all','全部领域'],...DOMAIN_REGISTRY].map(([id,n])=>`<a href="#catalog?domain=${id}" class="${VIEW.domain===id?'active':''}" ${VIEW.domain===id?'aria-current="page"':''}>${n}</a>`).join('')}</nav>`:group==='input'?`<div class="navcaption">制作入口</div><nav class="domain-nav"><a href="#input">新建需求</a><a href="#records">制作记录与待继续</a><a href="#teaching">导入教学需求</a></nav>`:group==='results'?`<div class="navcaption">成果处理</div><nav class="domain-nav"><a href="#results">全部成果</a><a href="#jury">版本审阅</a><a href="#delivery">交付预检</a><a href="#feedback">反馈与候选</a></nav>`:'';return `<aside class="sidebar r2-sidebar"><a class="brand" href="#catalog"><div class="brand-mark" aria-hidden="true"></div><div class="wordmark">DESIGN<em>-</em>LAB<small>设计实验室</small></div></a><nav class="nav primary-nav">${nav.map(([r,i,n])=>`<a href="#${r==='catalog'?'catalog?domain='+VIEW.domain:r}" class="${group===r?'active':''}">${icon(i)}${n}</a>`).join('')}</nav><div class="context-nav">${sub}</div><div class="sidebar-bottom"><nav class="nav"><a href="#connections">${icon('link')}连接与设置</a></nav><div class="sidebar-note">R2 界面参考 · 示例数据<br><span class="muted">实际软件与三项目未连接</span></div></div></aside>`;}
function renderR2(){const key=readHash();const group=['catalog','capability'].includes(key)?'catalog':['results','result','jury','delivery','feedback'].includes(key)?'results':['connections','states','components'].includes(key)?'connections':'input';const funcs={...pages,catalog:catalogR2,capability:capabilityR2,input:inputR2,records:recordsR2,results:resultsR2};const label=key==='records'?'制作记录':pageLabels[key]||'能力资产';document.body.classList.toggle('light',new URLSearchParams(location.search).get('theme')==='light');document.body.classList.add('r2');document.title='DESIGN-LAB R2 · '+label;document.querySelector('#app').innerHTML=`<div class="layout">${sidebarR2(group)}<main class="main"><header class="topbar"><div class="crumb">DESIGN-LAB　/　${label}${group==='catalog'&&VIEW.domain!=='all'?'　/　'+DOMAIN_NAMES[VIEW.domain]:''}</div><button class="global-trigger" data-r2="global">搜索能力、制作与成果 <kbd>Ctrl K</kbd></button><div class="top-actions"><span class="demo">R2 · 演示</span><button data-action="theme" class="ghost">${document.body.classList.contains('light')?'深色':'浅色'}</button></div></header><div class="content" data-page="${key}">${(funcs[key]||catalogR2)()}<footer class="footnote"><span>设计领域为配置；跨领域记录按唯一 ID 维护。</span><span>草稿与示例预览　/　真实执行未连接</span></footer></div><div class="activity-dock"><span><i class="dot"></i>示例草稿：品牌三维广告片　${badge('待继续','amber')}</span><button data-route="records">查看制作记录</button></div></main><nav class="mobile-nav"><a href="#catalog">${icon('asset')}能力资产</a><a href="#input">${icon('make')}分析制作</a><a href="#results">${icon('result')}成果反馈</a><a href="#connections">${icon('link')}连接</a></nav></div><dialog id="detail-dialog" class="detail-dialog" aria-label="资产详情"></dialog><dialog id="search-dialog" class="search-dialog" aria-label="全局搜索"><div class="row spread"><h2>搜索可用记录</h2><button data-r2="close-search">关闭</button></div><input id="global-query" aria-label="搜索名称或领域" placeholder="例如：音频、3D、广告片"><div id="global-results"></div><small>演示搜索；生产先按权限过滤再返回结果。</small></dialog><dialog id="domain-dialog" class="domain-dialog" aria-label="调整本次制作领域"><h2>本次制作涉及哪些领域？</h2><p>可多选；不会复制任务或清空输入。</p><div class="domain-checks">${DOMAIN_REGISTRY.map(([id,n])=>`<label class="checkrow"><input type="checkbox" value="${id}" ${taskDomains.includes(id)?'checked':''}>${n}</label>`).join('')}</div><button data-r2="save-domains" class="primary">保存领域选择</button></dialog>`;OLD_ATTACH();document.querySelectorAll('[data-draft]').forEach(el=>{const key=el.dataset.draft;if(Object.hasOwn(formDraft,key)){if(el.type==='checkbox')el.checked=formDraft[key];else el.value=formDraft[key];}for(const event of ['input','change'])el.addEventListener(event,()=>{formDraft[key]=el.type==='checkbox'?el.checked:el.value;persistDraft();});});attachR2();window.scrollTo(0,0);window.previewReady=true;}
function refreshItems(){document.querySelectorAll('[data-r2=grid],[data-r2=list]').forEach(b=>b.setAttribute('aria-pressed',String(VIEW.layout===b.dataset.r2)));const rows=mediaRows();const host=document.querySelector('#r2-items');if(!host)return;host.innerHTML=rows.map(card).join('');host.classList.toggle('as-list',VIEW.layout==='list');document.querySelector('#r2-count').textContent=rows.length+' 条演示记录';document.querySelector('#r2-empty').classList.toggle('hidden',rows.length>0);bindCards();}
function useItem(id){picked=ITEMS.find(x=>x.id===id)||ITEMS[0];taskDomains=[...picked.domains];taskAsset=picked;formDraft.software=picked.software;persistDraft();document.querySelector('#detail-dialog')?.close();location.hash='input';}
function bindCards(){document.querySelectorAll('[data-open]').forEach(b=>b.onclick=()=>{picked=ITEMS.find(x=>x.id===b.dataset.open);const d=document.querySelector('#detail-dialog');d.innerHTML=`<div class="row spread"><h2>${picked.name}</h2><button data-r2="close-detail">关闭</button></div>${art(picked.art,'media')}<p>${picked.desc}</p><div class="domain-tags">${picked.domains.map(x=>`<span>${DOMAIN_NAMES[x]}</span>`).join('')}</div>${facts([['资产类型',picked.kind],['示例范围',picked.scope],['交付目标',picked.outputs.join(' / ')],['软件候选',picked.software],['执行资格','未验证，不能声称可执行']])}<div class="line"></div><div class="row"><button class="primary" data-use="${picked.id}">用于本次制作</button><button data-full="${picked.id}">完整详情</button></div>`;d.querySelector('[data-r2="close-detail"]').onclick=()=>d.close();d.querySelector('[data-use]').onclick=()=>useItem(picked.id);d.querySelector('[data-full]').onclick=()=>{d.close();location.hash='capability?id='+picked.id;};d.showModal();});document.querySelectorAll('[data-use]').forEach(b=>b.onclick=()=>useItem(b.dataset.use));}
function searchResults(q){const needle=q.toLowerCase();const found=ITEMS.filter(c=>(c.name+c.software+c.domains.map(x=>DOMAIN_NAMES[x]).join('')).toLowerCase().includes(needle));const outs=OUTPUT_ROWS.filter(c=>(c.name+c.sub+c.domains.map(x=>DOMAIN_NAMES[x]).join('')).toLowerCase().includes(needle));const recordMatch=!needle||('品牌三维广告片制作记录待继续品牌3D视频'.toLowerCase().includes(needle));const rows=found.slice(0,6).map(c=>`<button data-search-id="${c.id}"><strong>${c.name}</strong><small>能力资产 · ${c.kind} · ${c.domains.map(x=>DOMAIN_NAMES[x]).join(' / ')}</small></button>`).join('')+outs.map(c=>`<button data-search-route="${c.route}"><strong>${c.name}</strong><small>成果 · ${c.sub}</small></button>`).join('')+(recordMatch?'<button data-search-route="records"><strong>品牌三维广告片</strong><small>制作记录 · 待继续 · 示例</small></button>':'');document.querySelector('#global-results').innerHTML=rows||'<p class="muted">没有匹配记录，请调整关键词。</p>';document.querySelectorAll('[data-search-id]').forEach(b=>b.onclick=()=>{picked=ITEMS.find(x=>x.id===b.dataset.searchId);document.querySelector('#search-dialog').close();location.hash='capability?id='+picked.id;});document.querySelectorAll('[data-search-route]').forEach(b=>b.onclick=()=>{document.querySelector('#search-dialog').close();location.hash=b.dataset.searchRoute;});}
function attachR2(){bindCards();document.querySelectorAll('.domain-nav a').forEach(a=>{if(a.getAttribute('href')===location.hash)a.setAttribute('aria-current','page');});document.querySelectorAll('.mobile-nav a').forEach(a=>a.classList.toggle('active',a.getAttribute('href')==='#'+(['catalog','capability'].includes(readHash())?'catalog':['results','result','jury','delivery','feedback'].includes(readHash())?'results':['connections','states','components'].includes(readHash())?'connections':'input')));document.querySelector('#mobile-domain')?.addEventListener('change',e=>{location.hash='catalog?domain='+e.target.value;});document.querySelector('[data-action=theme]').onclick=()=>{document.body.classList.toggle('light');const u=new URL(location.href);u.searchParams.set('theme',document.body.classList.contains('light')?'light':'dark');history.replaceState(null,'',u);document.querySelector('[data-action=theme]').textContent=document.body.classList.contains('light')?'深色':'浅色';};document.querySelector('#r2-query')?.addEventListener('input',e=>{VIEW.query=e.target.value;refreshItems();});document.querySelectorAll('[data-kind]').forEach(b=>b.onclick=()=>{VIEW.kind=b.dataset.kind;document.querySelectorAll('[data-kind]').forEach(x=>x.classList.toggle('selected',x===b));refreshItems();});for(const [id,key] of [['r2-output','output'],['r2-range','range'],['r2-scene','scene'],['r2-style','style'],['r2-method','method'],['r2-software','software']])document.querySelector('#'+id)?.addEventListener('change',e=>{VIEW[key]=e.target.value;refreshItems();});document.querySelectorAll('[data-r2]').forEach(b=>b.addEventListener('click',()=>{const act=b.dataset.r2;if(act==='clear'){VIEW={...VIEW,query:'',kind:'全部资产',output:'all',scene:'all',range:'all',style:'all',method:'all',software:'all'};renderR2();}else if(act==='grid'||act==='list'){VIEW.layout=act;refreshItems();}else if(act==='more'){document.querySelector('#r2-more').classList.toggle('hidden');document.querySelector('.r2-filters').classList.toggle('mobile-filters-open');b.setAttribute('aria-expanded',String(!document.querySelector('#r2-more').classList.contains('hidden')));}else if(act==='global'){searchResults('');if(!document.querySelector('#search-dialog').open)document.querySelector('#search-dialog').showModal();document.querySelector('#global-query').focus();}else if(act==='close-search')document.querySelector('#search-dialog').close();else if(act==='edit-domains')document.querySelector('#domain-dialog').showModal();else if(act==='save-domains'){const values=[...document.querySelectorAll('#domain-dialog input:checked')].map(x=>x.value);if(!values.length){toast('至少选择一个领域。');return;}taskDomains=values;persistDraft();document.querySelector('#domain-dialog').close();renderR2();document.querySelector('[data-r2=edit-domains]').focus();}}));bindOutputFilters();document.querySelector('#global-query').addEventListener('input',e=>searchResults(e.target.value));}
window.removeEventListener('hashchange',render);window.addEventListener('hashchange',renderR2);document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();searchResults('');if(!document.querySelector('#search-dialog').open)document.querySelector('#search-dialog').showModal();document.querySelector('#global-query').focus();}});renderR2();
